def clasificar(edad):
    if edad < 18:
        return "menor"
    else:
        return "adulto"

def signo(numero):
    if numero > 0:
        return "positivo"
    elif numero < 0:
        return "negativo"
    else:
        return "cero"

def nota_con_letra(puntaje):
    if puntaje >= 90:
        return "A"
    elif puntaje >= 80:
        return "B"
    elif puntaje >= 70:
        return "C"
    elif puntaje >= 60:
        return "D"
    else:
        return "F"
